INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@gpc_p34, 'Silk protein shine-drop hair serum, 100ml. Glass-hair finish, frizz control.', 'A few drops of this silk protein infused serum coat each hair strand for an instant, glossy glass-hair finish. Controls flyaways and static without weighing hair down or leaving it greasy. Suitable for daily use on all hair types, including coloured and keratin-treated hair. Bottled with a precision dropper for controlled, low-wastage dispensing.');
