INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@cwf_p1, 'Solid sheesham wood 3-seater sofa with classic hand-carved frame and cushioned seating.', 'Crafted from kiln-dried solid sheesham wood sourced from Rajasthan timber yards, this 3-seater sofa features traditional hand-carved motifs on the frame and armrests. High-density foam cushions are wrapped in tear-resistant fabric upholstery suited for residential and hospitality use. Finished with multi-coat lacquer for durability against humidity and termites. Bulk order customization available on fabric colour and wood polish shade; MOQ applies for export consignments.');
