INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@cwf_p2, 'Solid sheesham wood 2-seater sofa with carved frame and premium cushioning.', 'This 2-seater sofa is built on a solid sheesham wood frame with dovetail joinery for long-term structural stability. Seat and back cushions use high-resilience foam wrapped in durable upholstery fabric resistant to daily wear. A hand-applied matte lacquer finish protects the wood from moisture and pests. Suitable for hotel lobbies, waiting areas and residential living rooms; custom fabric options available on bulk orders.');
