INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@cwf_p3, 'Round solid wood coffee table with a turned pedestal base and smooth polished top.', 'Manufactured from seasoned solid sheesham wood, this round coffee table has a hand-turned pedestal base for stability on any flooring. The tabletop is sanded and finished with a scratch-resistant lacquer coat suited for daily household or cafe use. Compact footprint makes it ideal for apartment living rooms and hospitality lounges. Flat-pack assembly hardware included for easier bulk shipping.');
