INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@cwf_p8, '5-tier freestanding wooden bookshelf with reinforced shelving.', 'This 5-tier bookshelf is constructed on a solid wood frame with engineered wood shelf panels rated to carry heavy book loads without sagging. Each shelf is reinforced with rear cross-bracing for stability on uneven flooring. The unit ships knocked-down with pre-drilled holes for quick on-site assembly. Commonly ordered in bulk by libraries, schools and office fit-out contractors.');
