INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@cwf_p14, 'Storage ottoman with a lift-lid seat cushion on a solid wood base.', 'This ottoman pouffe combines a solid sheesham wood base with a lift-lid upholstered top that opens to reveal internal storage space. The cushion top is padded with high-density foam and finished in a durable, easy-clean fabric. Wooden legs are sealed against moisture for long-term use in humid climates. Frequently ordered in bulk mixed-colour batches by home decor retailers.');
