INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@cwf_p16, 'Wall-mounted 3-tier solid wood shelf unit for compact display storage.', 'This wall-mounted shelf unit is milled from solid sheesham wood and features three fixed tiers suitable for books, decor items or kitchen storage. Concealed mounting brackets and hardware are included for a clean wall-fixed look. Each shelf edge is sanded smooth and sealed with a protective lacquer coat. Ships flat-packed in bulk cartons to minimise freight cost for large orders.');
