INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@cwf_p17, 'Triangular corner display cabinet with glass-front doors and adjustable shelves.', 'This corner cabinet is designed to fit efficiently into unused room corners, featuring tempered glass-front doors and three adjustable interior shelves. The frame is built from solid sheesham wood joined to an engineered wood back panel for weight reduction during shipping. A locking mechanism is available as an optional add-on for retail display use. Bulk orders are commonly placed by furniture showrooms and gift retailers.');
