INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@cwf_p20, 'Traditional solid wood rocking chair with a hand-woven cane seat.', 'Handcrafted from solid sheesham wood, this rocking chair features a hand-woven cane seat and backrest for breathable, comfortable seating. Rockers are shaped and balanced for smooth, stable motion on hard flooring. The wood is treated with an anti-termite solution before a protective lacquer finish is applied. Ordered in bulk by resorts, verandah furnishers and heritage-style home decor retailers.');
