INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@cwf_p25, 'Solid wood table lamp base with a standard E27 socket fitting.', 'This lamp base is hand-turned from solid sheesham wood and fitted with a standard E27 socket and a two-metre fabric-braided cord. The base is weighted internally for stability and comes with a felt underside to protect furniture surfaces. Sold as a base only, allowing retailers to pair it with shades from their own range. Bulk orders are common from lighting distributors and home decor exporters.');
