INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@cwf_p26, 'Set of 3 floating wood wall shelves with concealed mounting brackets.', 'This set of three floating shelves is milled from solid sheesham wood in graduated widths for a staggered wall display arrangement. Concealed steel brackets are pre-fitted into the underside of each shelf for a clean, mount-free appearance once installed. Edges are rounded and sanded smooth before a matte lacquer finish is applied. A popular bulk decor item for home improvement and lifestyle retail chains.');
