INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@cwf_p27, 'Rectangular wooden serving tray with cut-out handles and a decorative lacquer finish.', 'This serving tray is machined from solid wood with integrated cut-out handles for easy carrying and a raised rim to contain items securely. The surface receives a food-safe lacquer finish available in multiple decorative colours. Corners are rounded and sanded to remove sharp edges for safe daily handling. Bulk ordered by hospitality suppliers and gifting hamper assemblers.');
