INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@cwf_p28, '3-tier solid wood plant stand for staggered indoor plant display.', 'This planter stand is built from solid sheesham wood with three staggered platform tiers, each sized to hold a standard potted plant. Legs are splayed for stability and fitted with protective floor caps. A water-resistant lacquer coating guards against moisture damage from watering. Frequently ordered in bulk by nursery retailers and home decor stores for indoor plant displays.');
