INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@cwf_p29, 'Hand-carved solid wood wall art panel with a traditional floral motif.', 'This wall art panel is hand-carved from solid wood by skilled artisans, depicting a traditional floral motif popular in Rajasthani decor. The panel is finished in a natural wood-tone lacquer that highlights the depth of the carving. Rear-mounted hanging brackets are pre-fitted for straightforward wall installation. A signature bulk decor item for boutique hotels and export gift catalogues.');
