INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@cwf_p31, 'Freestanding wooden magazine rack with slatted sides and a top carry handle.', 'This magazine rack is built from solid wood slats joined to a stable base, with a cut-out top handle for easy relocation. The slatted side panels allow magazines and newspapers to be organised for quick visibility and access. A light lacquer finish protects the wood while retaining its natural grain look. Common bulk purchase item for waiting rooms, lounges and home decor retailers.');
