(@bsi_vendor, (SELECT id FROM categories WHERE slug='mfg-stationery-office'), @bsi_brand, (SELECT id FROM tax_classes WHERE code='gst18'), (SELECT id FROM units WHERE code='pcs'), 'Paper Punching Machine - Double Hole', 'bsi-paper-punching-machine-double-hole', 'Double-hole paper punching machine with a metal base and up to 20-sheet capacity, sold individually.', 'simple', 'new', 'exclusive', 0, 0, 'vendor', 'published', 5, 5, 'both');
INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@bsi_p33, 'Double-hole punching machine, metal base, punches up to 20 sheets.', 'The reinforced metal base and lever mechanism punch clean, standard-spaced double holes through up to 20 sheets at a time. A removable paper-chip tray keeps the desk area clean between uses. Standard equipment for filing rooms, schools and print-finishing desks. Sold individually; MOQ 5 pieces.');
