(@sac_vendor, @sac_cat_car, @sac_brand, @sac_tax_gst28, @sac_unit_pcs, 'Radiator Assembly - Aluminium Core with Plastic Tank', 'sac-radiator-assembly-aluminium-core', 'Brazed aluminium-core radiator with reinforced plastic end tanks for efficient engine cooling in passenger cars.', 'simple', 'new', 'exclusive', 0, 0, 'vendor', 'published', 5, 1, 'both');
INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@sac_p3, 'Aluminium-core, plastic-tank radiator assembly with brazed fins for efficient passenger car cooling.', 'The radiator core is built from brazed aluminium fins and tubes for efficient heat rejection, paired with glass-reinforced nylon end tanks rated for continuous coolant temperature exposure. Each unit is pressure-tested to 1.5 bar before packing to rule out leaks. Mounting brackets and inlet/outlet spigots match OEM dimensions for bolt-on fitment. Recommended for wholesale distributors stocking common passenger car models.');
