INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@sac_p4, 'Pleated paper engine air filter cartridge, high dust-holding capacity, direct OEM-fit replacement.', 'This air filter cartridge uses a multi-pleat cellulose paper media for high dust-holding capacity while maintaining low restriction to airflow. The rigid frame is moulded to match OEM housing dimensions for a leak-free seal. Filtration efficiency exceeds 98 percent for particles above 5 microns. Packed in bulk cartons suitable for wholesale and service-centre distribution.');
