INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@sac_p6, 'Heavy-duty front coil spring, shot-peened alloy steel, for consistent load-bearing suspension performance.', 'Cold-formed from shot-peened chrome-silicon alloy steel wire, this front suspension coil spring is heat-treated and powder-coated for corrosion resistance. Free length and wire diameter are matched to OEM specification to preserve factory ride height. Each spring is load-tested before dispatch. Suited for passenger car service and replacement applications.');
