(@sac_vendor, @sac_cat_car, @sac_brand, @sac_tax_gst18, @sac_unit_pcs, 'Car Sun Shade - Foldable Windshield Type', 'sac-car-sun-shade-foldable-windshield', 'Foldable reflective windshield sun shade that blocks UV heat and protects the dashboard from sun damage.', 'simple', 'new', 'exclusive', 0, 0, 'vendor', 'published', 24, 6, 'both');
INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@sac_p7, 'Foldable reflective windshield sun shade, universal fit, blocks UV heat and protects the dashboard.', 'Constructed from a reflective aluminium-laminated non-woven fabric over a spring-steel folding frame, this sun shade collapses flat for compact storage. It blocks a large share of incoming UV and infrared heat, keeping cabin temperatures lower in parked vehicles. The universal size fits most hatchback and sedan windshields. Supplied with a drawstring storage pouch.');
