(@sac_vendor, @sac_cat_car, @sac_brand, @sac_tax_gst28, @sac_unit_pcs, 'Engine Mounting Bush - Rubber Bonded Steel', 'sac-engine-mounting-bush-rubber-steel', 'Rubber-bonded steel engine mounting bush designed to absorb vibration and reduce noise transfer.', 'simple', 'new', 'exclusive', 0, 0, 'vendor', 'published', 20, 4, 'both');
INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@sac_p8, 'Rubber-bonded steel engine mounting bush with OEM-equivalent hardness rating for vibration damping.', 'This engine mounting bush bonds a natural-rubber compound to a steel sleeve and outer shell using a vulcanisation process for long-term adhesion under heat and load. The rubber hardness is matched to OEM rating to preserve intended NVH characteristics. Dimensions are held to tight tolerance for press-fit installation. Recommended for periodic replacement during suspension and engine service.');
