INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@sac_p13, 'Anti-slip, non-reflective dashboard mat that cushions and protects the dashboard from sun and dust.', 'Cut from a non-reflective, textured PVC-fibre composite, this dashboard mat reduces windshield glare caused by dashboard reflection while cushioning items placed on it. The high-friction underside grips the dashboard surface without adhesive. It also shields the dashboard finish from prolonged UV exposure. Sized to fit common passenger car dashboards.');
