INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@sac_p15, 'Soft-touch silicone remote key cover case, scratch and impact protection, multiple colours.', 'Moulded from food-grade silicone, this key cover case wraps around common flip and smart-key remote fobs to guard against scratches, dust, and minor drops. The buttons remain fully tactile through the silicone layer. A moulded key-ring loop is included for convenience. Supplied in a range of colours suited to retail accessory racks.');
