INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@sac_p16, 'PU leather gear knob cover, universal slip-fit, refreshes grip and cabin styling.', 'This gear knob cover is stitched from PU leather over a foam cushion and slips directly over the factory gear knob using an elastic drawstring base. It renews grip feel on worn factory knobs while adding a stitched leather look to the cabin. The universal design fits most standard-shape gear knobs. Offered in multiple colours for accessory wholesalers.');
