(@sac_vendor, @sac_cat_car, @sac_brand, @sac_tax_gst18, @sac_unit_pcs, 'Chrome Side Body Molding Strip', 'sac-chrome-side-body-molding-strip', 'Self-adhesive body side moulding strip that protects door panels from minor scuffs and door dings.', 'variant', 'new', 'exclusive', 0, 0, 'vendor', 'published', 30, 6, 'both');
INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@sac_p18, 'Self-adhesive chrome-finish body side moulding strip, protects doors from scuffs and dings.', 'This body side moulding strip is extruded from flexible PVC with a bright electroplated or matte finish and a pre-applied adhesive backing. It runs along the door line to absorb minor scuffs and door-to-door contact in parking areas. The strip is pre-cut to standard sedan door lengths and can be trimmed on site. Offered in multiple finish colours.');
