(@sac_vendor, @sac_cat_2w, @sac_brand, @sac_tax_gst28, @sac_unit_set, 'Brake Shoe Set (Rear Drum)', 'sac-brake-shoe-set-rear-drum', 'Rear drum brake shoe set with riveted friction lining for consistent motorcycle braking performance.', 'simple', 'new', 'exclusive', 0, 0, 'vendor', 'published', 50, 10, 'both');
INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@sac_p21, 'Rear drum brake shoe set, riveted friction lining, OEM-spec performance for motorcycles.', 'Each brake shoe in this set is fitted with a riveted friction lining formulated for consistent bite and controlled wear under drum braking conditions. The shoe arc and pin spacing are held to OEM tolerance for direct fitment. Return springs are included in every set. Recommended for periodic rear brake service on commuter motorcycles.');
INSERT INTO product_mshops (product_id, mshop_id, status, listed_at) VALUES
