(@sac_vendor, @sac_cat_2w, @sac_brand, @sac_tax_gst18, @sac_unit_pcs, 'Chrome Number Plate Frame - Motorcycle', 'sac-chrome-number-plate-frame-bike', 'Electroplated number plate frame sized for standard motorcycle plates, offering a corrosion-resistant finish.', 'variant', 'new', 'exclusive', 0, 0, 'vendor', 'published', 60, 12, 'both');
INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@sac_p30, 'Electroplated motorcycle number plate frame, standard IND size, corrosion-resistant finish.', 'Stamped from cold-rolled steel and electroplated for a bright, corrosion-resistant finish, this number plate frame is sized to standard Indian motorcycle plates. Pre-drilled mounting holes align with common rear-fender bolt patterns for quick installation. The frame edge is rolled to prevent sharp burrs. Offered in multiple finish colours.');
