(@sac_vendor, @sac_cat_2w, @sac_brand, @sac_tax_gst18, @sac_unit_pcs, 'Fuel Tank Cover - PU Leather', 'sac-fuel-tank-cover-pu-leather', 'PU leather fuel tank cover with elastic hem that protects the tank paint from scratches and sun fading.', 'variant', 'new', 'exclusive', 0, 0, 'vendor', 'published', 20, 4, 'both');
INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@sac_p31, 'PU leather motorcycle fuel tank cover, elastic hem fit, protects paint from scratches and sun.', 'Tailored from PU leather with a stretch-elastic hem, this fuel tank cover slips over the factory tank to guard the paint finish from scratches, keys, and prolonged sun exposure. Reinforced stitching at stress points extends service life under regular use. The cover is designed for tool-free installation and removal. Available in multiple colours for accessory wholesalers.');
