(@sac_vendor, @sac_cat_2w, @sac_brand, @sac_tax_gst18, @sac_unit_set, 'Bike Wheel Rim Sticker Kit', 'sac-bike-wheel-rim-sticker-kit', 'Reflective wheel rim sticker kit for motorcycles that adds a custom stripe and improves night visibility.', 'variant', 'new', 'exclusive', 0, 0, 'vendor', 'published', 50, 10, 'both');
INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@sac_p33, 'Reflective motorcycle wheel rim sticker kit, adds custom stripe, improves night visibility, multiple colours.', 'This rim sticker kit uses a reflective, weatherproof vinyl strip that applies along the wheel rim channel to add a custom colour stripe. The reflective layer improves side visibility to other road users at night. Each kit includes pre-cut strips sized for standard 17 to 18 inch motorcycle rims along with an application squeegee. Offered in a range of colours for retail accessory racks.');
