INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@sac_p35, 'Bolt-on tubular motorcycle crash guard, protects engine and riders legs during low-speed falls.', 'Fabricated from heavy-gauge mild steel tubing and finished with a bright electroplated or matte black coating, this crash guard bolts onto the frames existing engine-mount points. It shields the engine casing and the riders legs from direct ground contact during a low-speed tip-over. Reinforced corner welds are tested for impact strength before dispatch. Offered in two finish options.');
