INSERT INTO product_content (product_id, short_description, full_description) VALUES
(@glt_p1, 'GOTS-certified organic cotton grey fabric, 60 inch width, sold in bulk rolls by weight.', 'This unbleached, undyed organic cotton grey fabric is woven from 100% certified organic cotton yarn and is suitable for downstream dyeing, printing and garment cutting. Ideal for manufacturers building GOTS-certified apparel and home-textile lines. Custom GSM and width available on request for bulk orders.');
