-- =====================================================================
-- manufacturer_products_demo.sql  —  MANUFACTURER SAMPLE CATALOG (NOT production)
-- ---------------------------------------------------------------------
-- 15 manufacturers (vendors.party_type='manufacturer', see 70_manufacturer.sql)
-- across 15 industries, each with one manufacturing unit (mshops) and
-- 30-40 products (mix of simple and multi-variant products spanning
-- size/color/storage/pack-size/capacity), listed into the monline B2B
-- catalog via product_mshops.
--
-- Idempotent master data (categories/tax_classes/units/attributes/values):
-- INSERT IGNORE / ON DUPLICATE KEY, safe to re-run. Manufacturer/product
-- rows are NOT idempotent (plain AUTO_INCREMENT inserts) — running this
-- twice creates two copies. Run once:
--   mysql -uroot test < database/sql/manufacturer_products_demo.sql
--
-- Assumes the base schema (run_all.sql) is already applied. Does not
-- touch business_types, hsn_sac_codes, or existing vendors/categories —
-- all new master rows use an `mfg-` slug/code prefix or a distinct
-- attribute code to avoid colliding with 99_demo_seed.sql or any other
-- seed already loaded.
-- =====================================================================
SET FOREIGN_KEY_CHECKS = 0;
SET autocommit = 0;
START TRANSACTION;

-- ---------------------------------------------------------------------
-- A. Tax classes (GST slabs used by these products only; distinct codes
--    so this is a no-op if a project-wide gst0..gst28 set already exists
--    under the same codes, and additive otherwise).
-- ---------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`);

SELECT tc.id, r.half, r.half, r.full, '2024-01-01', 'active'
FROM `tax_classes` tc
JOIN (
  SELECT 'gst0' AS code, 0.00 AS half, 0.00 AS full UNION ALL
  SELECT 'gst5', 2.50, 5.00 UNION ALL
  SELECT 'gst12', 6.00, 12.00 UNION ALL
  SELECT 'gst18', 9.00, 18.00 UNION ALL
  SELECT 'gst28', 14.00, 28.00
) r ON r.code = tc.code
WHERE NOT EXISTS (
  SELECT 1 FROM `tax_rates` WHERE `tax_class_id` = tc.id AND `valid_from` = '2024-01-01'
);

-- ---------------------------------------------------------------------
-- B. Units of measure (distinct codes; no-op if already present).
-- ---------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`);

-- ---------------------------------------------------------------------
-- C. Variant-defining attributes + values.
--    'size' and 'color' reuse the codes 17_product_variants.sql seeds
--    (idempotent either way); 'storage' likewise. 'pack_size' and
--    'capacity' are new, for FMCG/beverage/personal-care and
--    appliance/kitchenware variants respectively.
-- ---------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`);

SET @has_uq := (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'attribute_values' AND INDEX_NAME = 'uq_attrval_attr_value');
SET @ddl := IF(@has_uq = 0, 'ALTER TABLE `attribute_values` ADD UNIQUE KEY `uq_attrval_attr_value` (`attribute_id`,`value`)', 'SELECT 1');
PREPARE _st FROM @ddl; EXECUTE _st; DEALLOCATE PREPARE _st;

SELECT a.id, v.value, v.so FROM `attributes` a
JOIN (
  SELECT 'size' AS code, 'XS' AS value, 1 AS so UNION ALL SELECT 'size','S',2 UNION ALL SELECT 'size','M',3
  UNION ALL SELECT 'size','L',4 UNION ALL SELECT 'size','XL',5 UNION ALL SELECT 'size','XXL',6
  UNION ALL SELECT 'color','Red',1 UNION ALL SELECT 'color','Black',2 UNION ALL SELECT 'color','Blue',3
  UNION ALL SELECT 'color','White',4 UNION ALL SELECT 'color','Green',5 UNION ALL SELECT 'color','Grey',6
  UNION ALL SELECT 'color','Yellow',7 UNION ALL SELECT 'color','Orange',8 UNION ALL SELECT 'color','Pink',9
  UNION ALL SELECT 'color','Purple',10 UNION ALL SELECT 'color','Beige',11 UNION ALL SELECT 'color','Maroon',12
  UNION ALL SELECT 'color','Navy',13 UNION ALL SELECT 'color','Silver',14 UNION ALL SELECT 'color','Gold',15
  UNION ALL SELECT 'storage','64GB',1 UNION ALL SELECT 'storage','128GB',2 UNION ALL SELECT 'storage','256GB',3 UNION ALL SELECT 'storage','512GB',4
  UNION ALL SELECT 'pack_size','50g',1 UNION ALL SELECT 'pack_size','100g',2 UNION ALL SELECT 'pack_size','200g',3
  UNION ALL SELECT 'pack_size','250g',4 UNION ALL SELECT 'pack_size','500g',5 UNION ALL SELECT 'pack_size','1kg',6
  UNION ALL SELECT 'pack_size','2kg',7 UNION ALL SELECT 'pack_size','5kg',8 UNION ALL SELECT 'pack_size','100ml',9
  UNION ALL SELECT 'pack_size','200ml',10 UNION ALL SELECT 'pack_size','250ml',11 UNION ALL SELECT 'pack_size','500ml',12 UNION ALL SELECT 'pack_size','1L',13
  UNION ALL SELECT 'pack_size','2L',14
  UNION ALL SELECT 'capacity','0.5L',1 UNION ALL SELECT 'capacity','1L',2 UNION ALL SELECT 'capacity','1.5L',3
  UNION ALL SELECT 'capacity','2L',4 UNION ALL SELECT 'capacity','3L',5 UNION ALL SELECT 'capacity','5L',6
  UNION ALL SELECT 'capacity','7Kg',7 UNION ALL SELECT 'capacity','1Ton',8 UNION ALL SELECT 'capacity','1.5Ton',9
  UNION ALL SELECT 'capacity','2Ton',10
) v ON v.code = a.code
ON DUPLICATE KEY UPDATE `sort_order` = VALUES(`sort_order`);

-- ---------------------------------------------------------------------
-- D. Categories — one parent per manufacturer's industry, 2-3 children
--    each, `mfg-` prefixed slugs so nothing collides with existing
--    trees (e.g. the demo seed's bare 'footwear'/'electronics').
-- ---------------------------------------------------------------------
SET @cat_textiles := LAST_INSERT_ID();

SET @cat_footwear := LAST_INSERT_ID();

SET @cat_electronics := LAST_INSERT_ID();

SET @cat_appliances := LAST_INSERT_ID();

SET @cat_foods := LAST_INSERT_ID();

SET @cat_beverages := LAST_INSERT_ID();

SET @cat_personalcare := LAST_INSERT_ID();

SET @cat_furniture := LAST_INSERT_ID();

SET @cat_kitchenware := LAST_INSERT_ID();

SET @cat_toys := LAST_INSERT_ID();

SET @cat_stationery := LAST_INSERT_ID();

SET @cat_sports := LAST_INSERT_ID();

SET @cat_industrial := LAST_INSERT_ID();

SET @cat_automotive := LAST_INSERT_ID();

