SELECT 'manufacturer demo catalog loaded' AS info,
 (SELECT COUNT(*) FROM vendors WHERE party_type='manufacturer') AS manufacturers,
 (SELECT COUNT(*) FROM mshops) AS mshops,
 (SELECT COUNT(*) FROM products WHERE vendor_id IN (SELECT id FROM vendors WHERE party_type='manufacturer')) AS products,
 (SELECT COUNT(*) FROM product_variants WHERE vendor_id IN (SELECT id FROM vendors WHERE party_type='manufacturer')) AS variants,
 (SELECT COUNT(*) FROM product_mshops) AS catalog_listings;
